// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address baseToken_, address nft_, uint128 virtualBaseTokenReserves_, uint128 virtualNftReserves_, uint56 changeFee_, uint16 feeRate_, bytes32 merkleRoot_, bool useStolenNftOracle_, bool payRoyalties_) public {
        vm.assume(baseToken_ != address(0));

        bool ok;
        try c.initialize(
            baseToken_,
            nft_,
            virtualBaseTokenReserves_,
            virtualNftReserves_,
            changeFee_,
            feeRate_,
            merkleRoot_,
            useStolenNftOracle_,
            payRoyalties_
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.baseToken() == baseToken_);
        } else {
            assertTrue(!ok || c.baseToken() == baseToken_);
        }
    }
}
